/* Original fixed-route practice: 17 responses, five conversations with 2 questions, four announcements with 2 questions, three talks with 4 questions. Each form has separate scripts. */
const listeningExtraSources=[];
function addListeningForm(responses,conversations,announcements,talks){
  const lines=t=>t.trim().split('\n').map(x=>x.trim()).filter(Boolean);
  const r=lines(responses).map(l=>l.split('|'));
  const groups=t=>t.trim().split(/\n\s*\n/).map(g=>{const [source,...q]=lines(g);return [source.replace(/~/g,'\n'),q.map(l=>l.split('|'))]});
  listeningExtraSources.push({r,c:groups(conversations),a:groups(announcements),t:groups(talks)});
}
function attachListeningForms(){
  if(listeningExtraSources.length>23)throw Error('Too many additional listening forms');
  listeningExtraSources.forEach(({r,c,a,t},index)=>{
    const form=index+1,items=listeningPracticeForms[form];
    if(r.length!==17||c.length!==5||a.length!==4||t.length!==3)throw Error('Incomplete form '+(form+1));
    let audioNo=0;
    function addAudio(source){const audio='audio/exam-listening/'+(form+1)+'-'+(++audioNo)+'.mp3';listeningExamAudio.push({audio,source});return audio;}
    function item(type,source,audio,ask,answer,wrong,why){
      const options=[answer,...wrong];
      if(options.length!==4||new Set(options).size!==4||options.some(x=>!x))throw Error('Invalid options: '+ask);
      const rotation=(form+items.length*3)%4;options.push(...options.splice(0,rotation));
      items.push({type,source,audio,ask,options,answer,why});
    }
    r.forEach(([source,answer,...wrong],i)=>item('Listen and Choose a Response',source,addAudio(source),'Choose the most appropriate response.',answer,wrong,'Appropriate response: '+answer));
    [[c,'Listen to a Conversation',2],[a,'Listen to an Announcement',2],[t,'Listen to an Academic Talk',4]].forEach(([groups,type,n])=>groups.forEach(([source,qs])=>{
      if(qs.length!==n)throw Error('Invalid group: '+source);
      const audio=addAudio(source);
      qs.forEach(([ask,answer,...wrong])=>item(type,source,audio,ask,answer,wrong,'Correct answer: '+answer+'. Review the recording for the evidence.'));
    }));
    if(items.length!==47)throw Error('Bad count '+form);
  });
}

